head.script:
// 테스트 설명, 유효성 값 설정
//  - "Header/Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성)
//    본 샘플(_1)은 Body Column 에 설정, column_P_fixColumnWidth_2 는 병합된 Header Column 에 설정
//  - 본 샘플(_1) : 마우스 Drag / 마우스 포인터 / autoFit(allColumn, lastColumn) / resize 축
//    setColumnWidth(), 병합된 Header Column, RowNum/RowStatus Column 항목은 column_P_fixColumnWidth_2 소유
scwin.tData = {
    "description" : "[column > P > fixColumnWidth]<br/>Column 의 너비(Width)를 고정할지 설정합니다.",
    "validation" : [
        "true 설정 시, 마우스로 Column 의 너비를 변경할 수 없습니다.",
        "true 설정 시, autoFit='allColumn' 일때 너비 자동 조정 대상에서 제외되어 설정된 너비를 유지합니다.",
        "true 설정 시, Header Column 의 오른쪽 경계에 마우스 오버해도 마우스 포인터가 'col-resize' 로 변경되지 않습니다.",
        "false 설정 시, Column 의 너비를 고정하지 않습니다.",
        "미설정 시, Column 의 너비를 고정하지 않습니다.",
        "false 설정 시, resize 속성과 autoFit 속성의 설정에 따라 Column 의 너비가 변경됩니다.",
        "autoFit='lastColumn' 일때 마지막 Column 은 fixColumnWidth 속성값에 관계없이 너비가 자동 조정됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean : 1=미설정 / 2=true / 3=false)
    con_fixColumnWidth.setValue("2");
    con_autoFit.setValue("allColumn");
    con_resize.setValue("1");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - fixColumnWidth(con 값) 는 첫번째 Body Column(code) 과 마지막 Body Column(memo) 에 설정
//    두번째(name), 세번째(qty) Column 은 미설정 (대조용)
//  - 각 Column 너비 100px, GridView 너비 600px (autoFit 미적용 시 오른쪽 여백 발생)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cFixColumnWidth = con_fixColumnWidth.getText();
    let cAutoFit = con_autoFit.getValue();
    let cResize = con_resize.getText();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] fixColumnWidth 는 첫번째(code), 마지막(memo) Column 에 설정, 각 Column 너비 100px, GridView 너비 600px\n[절차] Header Column 오른쪽 경계에 마우스 오버하여 포인터 확인 -> Drag 로 너비 변경\n[확인] Column 너비 확인 버튼으로 각 Column 너비 확인"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="number"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "code" : "P-1001", "name" : "무선 키보드", "qty" : 12, "memo" : "입고 대기" },
        { "code" : "P-1002", "name" : "광마우스", "qty" : 30, "memo" : "정상" },
        { "code" : "P-1003", "name" : "모니터 받침대", "qty" : 7, "memo" : "재고 부족" }
    ], false);

    // GridView 속성
    let attrGrid = '';
    attrGrid += (cAutoFit === '') ? '' : ' autoFit="' + cAutoFit + '"';
    attrGrid += (cResize === '') ? '' : ' resize="' + cResize + '"';

    // 검증 대상 Body Column 속성
    let attrFix = (cFixColumnWidth === '') ? '' : ' fixColumnWidth="' + cFixColumnWidth + '"';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:600px;height:150px;"' + attrGrid + '>';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="code"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="name"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="qty"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="code" value=""' + attrFix + '></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="qty" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="memo" value=""' + attrFix + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1, 2, 4 ~ 7 판정 출력 : 각 Column 의 화면 너비(Header Column 기준, px)
//  - validation 3(마우스 포인터) 은 Header Column 오른쪽 경계 마우스 오버로 직접 확인
scwin.btn_checkColumnWidth_onclick = function () {
    let arrHeader = ["column1", "column2", "column3", "column4"];
    let arrName = ["code", "name", "qty", "memo"];
    let arr = [];
    for (let i = 0; i < arrHeader.length; i++) {
        let th = document.querySelector("[id='" + target1.id + "_" + arrHeader[i] + "']");
        arr.push(arrName[i] + " : " + (th ? th.offsetWidth : "-"));
    }
    wf_body_bottom.getObj("scwin").setReturnValue("Column 너비 : " + arr.join(" / "));
}
